from pathlib import Path
import re,math
import markdown
p=Path(__file__).parent
source=(p/'ARTICLE.md').read_text()
md=markdown.Markdown(extensions=['extra','toc','sane_lists'],extension_configs={'toc':{'toc_depth':'2-2'}})
body=md.convert(source)
body=re.sub(r'(<h1[^>]*>)2B or Not 2B\? Building Grid Dodger with Strands Decider 2B(</h1>)',r'\1<span class="title-hook">2B or Not 2B?</span> <span class="title-detail">Building Grid Dodger with Strands Decider 2B</span>\2',body)
sections=len(re.findall(r'^## ',source,re.M))
body=re.sub(r'(<img[^>]+src="([^"]+)"[^>]*>)',r'<a href="\2" title="Open full-size image" target="_blank" rel="noopener noreferrer">\1</a>',body)
words=len(re.findall(r'\b[\w’-]+\b',source));minutes=math.ceil(words/220)
css='''
:root{color-scheme:light;--ink:#172a32;--muted:#526972;--line:#dce6e3;--accent:#13664c;--paper:#f8faf7}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.8 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
header{padding:18px 4vw;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;background:#eaf1eb}header strong{color:var(--accent)}
.layout{max-width:1440px;margin:auto;padding:48px 36px 100px;display:grid;grid-template-columns:220px minmax(0,960px);gap:64px}aside{position:sticky;top:24px;align-self:start;max-height:90vh;overflow:auto;font-size:13px;line-height:1.65;padding-right:12px}aside h2{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--accent);margin:0 0 14px}aside ul{padding-left:16px}aside li{margin:0 0 12px}aside a{text-decoration:none;color:var(--muted)}aside a:hover{color:var(--accent)}
.mobile-toc{display:none}article{min-width:0}h1{font-size:clamp(34px,4.3vw,56px);line-height:1.12;letter-spacing:-.045em;margin:0 0 24px;max-width:880px}.title-hook{display:block;font-size:clamp(42px,5.3vw,68px);line-height:1.08}.title-detail{display:block;margin-top:16px;font-size:clamp(26px,3vw,38px);line-height:1.16;letter-spacing:-.03em}article h2{font-size:30px;line-height:1.25;letter-spacing:-.025em;margin:64px 0 22px;max-width:800px;scroll-margin-top:28px}p,article>ul,article>ol{max-width:800px}p{margin:0 0 24px}a{color:var(--accent);text-underline-offset:3px}a:hover{color:#083d2c}strong{font-weight:700}em{color:var(--muted)}
img{display:block;width:100%;height:auto;border-radius:14px;border:1px solid #cad8d5}p:has(img){max-width:none;margin:34px 0 14px}p:has(img)+p:has(>em){font-size:14px;line-height:1.65;max-width:900px}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.65;margin:28px 0;background:white}th,td{text-align:left;vertical-align:top;padding:13px 12px;border-bottom:1px solid var(--line)}th{background:#e6eee8;color:#1d4c3d;font-size:12px}pre{padding:24px;background:#0b1a24;color:#dcefe8;border-radius:12px;overflow:auto;font-size:13px;line-height:1.7}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.85em}p code,li code,td code{background:#e8efea;padding:2px 5px;border-radius:4px}hr{border:0;border-top:1px solid var(--line);margin:52px 0}footer{font-size:13px;color:var(--muted);border-top:1px solid var(--line);padding-top:24px}
@media(max-width:1100px){.layout{display:block;max-width:980px;padding:36px 24px 70px}aside{position:static;max-height:none;margin-bottom:40px;border-bottom:1px solid var(--line)}aside .toc ul{columns:2;column-gap:28px}aside li{break-inside:avoid}}@media(max-width:1100px){aside{display:none}.mobile-toc{display:block;margin:0 0 28px;padding:10px 14px;border:1px solid var(--line);border-radius:8px;background:white;font-size:14px}.mobile-toc summary{cursor:pointer;min-height:32px;color:var(--accent);font-weight:600}.mobile-toc ul{padding-left:18px}}@media(max-width:600px){body{font-size:17px}.layout{padding:28px 18px 60px}header{font-size:10px;padding:14px 18px}article h2{font-size:26px;margin-top:44px}aside .toc ul{columns:1}table{display:block;overflow-x:auto}pre{padding:16px;font-size:12px}img{border-radius:8px}}
@media print{header,aside{display:none}.layout{display:block;padding:0;max-width:none}body{background:white;font-size:11pt}h1{font-size:30pt}article h2{break-after:avoid}img,pre,tr{break-inside:avoid}a{color:inherit}pre{white-space:pre-wrap}}
'''
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>2B or Not 2B? — Grid Dodger with Strands Decider 2B</title><style>{css}</style></head><body><header><strong>Grid Dodger / Field notes</strong><span>{minutes} min read</span></header><main class="layout"><aside><h2>In this article</h2>{md.toc}</aside><article><details class="mobile-toc"><summary>Contents · {sections} sections</summary>{md.toc}</details>{body}<footer>Grid Dodger · Build notes by Elyas Syed.</footer></article></main></body></html>'''
(p/'ARTICLE.html').write_text(html)
print(f'{words} words; approximately {minutes} minutes; HTML generated.')
